#!/usr/bin/env bash\nset -euo pipefail\n\nDIR="."\nN=10\nEXCLUDE=""\n\nwhile getopts ":d:n:e:" opt; do\n  case $opt in\n    d) DIR="$OPTARG";;\n    n) N="$OPTARG";;\n    e) EXCLUDE="$OPTARG";;\n    \?) echo "Invalid option -$OPTARG" >&2; exit 1;;\n  esac\n done\n\nif [[ ! -d "$DIR" ]]; then\n  echo "Directory $DIR does not exist" >&2\n  exit 1\nfi\n\n# Build find command\nFIND_CMD=(find "$DIR" -type f)\nif [[ -n "$EXCLUDE" ]]; then\n  FIND_CMD+=( ! -path "$EXCLUDE" )\nfi\n\n# Get sizes and sort\nprintf "%s\\n" "Scanning $DIR..." >&2\nmapfile -t entries < <(\n  "${FIND_CMD[@]}" -printf "%s %p\\n" 2>/dev/null |\n  sort -nr |\n  head -n "$N"\n)\n\nif [[ ${#entries[@]} -eq 0 ]]; then\n  echo "No files found."\n  exit 0\nfi\n\n# Print human readable\ni=1\nfor line in "${entries[@]}"; do\n  size_bytes=$(awk '{print $1}' <<<"$line")\n  path=$(awk '{sub($1 FS,""); print $0}' <<<"$line")\n  # human readable\n  if (( size_bytes >= 1073741824 )); then\n    hr=$(awk "BEGIN {printf \"%.2fGiB\", $size_bytes/1073741824}")\n  elif (( size_bytes >= 1048576 )); then\n    hr=$(awk "BEGIN {printf \"%.2fMiB\", $size_bytes/1048576}")\n  elif (( size_bytes >= 1024 )); then\n    hr=$(awk "BEGIN {printf \"%.2fKiB\", $size_bytes/1024}")\n  else\n    hr="${size_bytes}B"\n  fi\n  printf "%d. %s\\t%s\\n" "$i" "$path" "$hr"\n  ((i++))\ndone
